mapper.select:

WHERE 1=1

    AND p.pers_rut = #{rut}


    AND UPPER(p.pers_nombre) LIKE UPPER(#{nombre})



    ORDER BY #{orderBy} ${order}


    LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(p.pk_pers_id_persona) FROM persona p LEFT JOIN etnia e ON e.pk_etni_id_etnia = p.fk_pers_id_etnia LEFT JOIN nacionalidad n ON n.pk_naci_id_nacionalidad = p.fk_pers_id_nacionalidad LEFT JOIN estado_civil ec ON ec.pk_esci_id_estado_civil = p.fk_pers_id_estado_civil LEFT JOIN sexo sx ON sx.pk_sexo_id_sexo = p.fk_pers_id_sexo WHERE 1=1
AND p.pers_rut = #{rut}
AND UPPER(p.pers_nombre) LIKE UPPER(#{nombre})
